                setniHlavickoveFormy(dto) {
                    const that = this;
                    this.setniObsahovePolicko(dto.ObsahBase64);
                    this.$FormHlavicka.findFields().gfield("model", "apply", dto);
                    this.$FormHlavicka.gform("viewMode", "view");
                    if (this.$FormHlavickaDruha) {
                        this.$FormHlavickaDruha.findFields().gfield("model", "apply", dto);
                        this.$FormHlavickaDruha.gform("viewMode", "view");
                    }
                }
                setniObsahovePolicko(ObsahBase64) {
                    var that = this;
                    if (ObsahBase64) {
                        var Obsah = this.decodeBase64Unicode(ObsahBase64);
                        this.vytvorPokudNeniObsahVeHlavicce();
                        //this.$FormHlavickaObsahText!.html(Obsah);
                        var iframe = this.$iframeDiv[0];
                        if (iframe.contentWindow != null && iframe.contentWindow.document != null) {
                            iframe.contentWindow.document.open();
                            iframe.contentWindow.document.write(Obsah);
                            iframe.contentWindow.document.close();
                            this.$iframeDiv.on('load', function () {
                                that.resizeIframe();
                            });
                        }
                    }
                    // konec article
                    this.ObsahBase64 = ObsahBase64;
                }
                resizeIframe() {
                    if (this && this.$iframeDiv && this.$iframeDiv[0]) {
                        var obj = this.$iframeDiv[0];
                        if (obj.contentWindow != null && obj.contentWindow.document != null && obj.contentWindow.document.body != null) {
                            obj.style.height = obj.contentWindow.document.body.scrollHeight + 80 + 'px'; //30.3.2022 kuli verticalnímu scrollbaru zvětšen z 20 na 80
                        }
                    }
                }
                vytvorPokudNeniObsahVeHlavicce() {
                    if (this.$FormHlavickaObsahText == null) {
                        this.$FormHlavickaObsah.html("");
                        let wrp = $("<div>").appendTo(this.$FormHlavickaObsah);
                        this.$FormHlavickaObsahFade = $("<div class='elPod-Pruvodce-Obsah-fade'>").appendTo(wrp); // Bohouš
                        this.$FormHlavickaObsahText = $("<div class='elPod-Pruvodce-Obsah-text'>") // Bohouš
                            .appendTo(wrp);
                        this.$iframeDiv = $("<iframe src='javascript: void (0);' frameborder='0' border='0' width='100%' height='100%' allowtransparency='true' style='position: static;'>Nepodařilo se vykreslit</iframe>");
                        this.$iframeDiv.appendTo(this.$FormHlavickaObsahText);
                        this.actions.actObsahZobrazSkryj.visible(true);
                    }
                }
