                    JeOkSignRuc.gfield("option", "disabled", tempBool);
                    PrizVerif.gfield("option", "disabled", tempBool);
                    StavVerif.gfield("option", "disabled", tempBool);
                    // pkud je sign ruc disabnu selboxy
                    tempBool = ((JeSignRuc.gfield("getValue") && !JeOkSignRuc.gfield("getValue")) ? false : true);
                    PrizVerif.gfield("option", "disabled", tempBool);
                    StavVerif.gfield("option", "disabled", tempBool);
