                    inputDto.UOdes = (this.findFields("UOdes").length > 0) ? this.findFields("UOdes").gfield("getValue") : undefined;
                    inputDto.HodZFormChecked = this.Krok5VysledekFormu.HodZFormChecked;
                    inputDto.HodZFormPdf = this.Krok5VysledekFormu.HodZFormPdf;
