                    inputDto.IsMsgSigned = this.VysledekKrok1Call1.IsMsgSigned;
                    inputDto.DZPole = this.VysledekKrok1Call1.DZPole;
                    // RucniOvereni // pridetat texty do modelu k selectboxum
