                //#endregion
                //#region odeslat potvrzeni
                /**
                 * funkce pro odeslání potvrzení
                 */
                OdeslatPotvrzeni() {
                    const that = this;
                    this.log.trace("OdeslatPotvrzeni- start");
                    this.saveModelFromKork6();
                    var VytvoritSouborPodaniDto = {};
                    if (!this.Krok6VysledekFormu.NoCbx && (this.Krok6VysledekFormu.EmailCbx || this.Krok6VysledekFormu.DSCbx || this.Krok6VysledekFormu.PisCbx)) {
                        VytvoritSouborPodaniDto.TextPotvrz = this.Krok6VysledekFormu.TextPotvrz;
                        VytvoritSouborPodaniDto.IsPotvrzSigned = this.IsPotvrzSigned;
                        VytvoritSouborPodaniDto.EmailCbx = this.Krok6VysledekFormu.EmailCbx;
                        VytvoritSouborPodaniDto.EmailSignCbx = this.Krok6VysledekFormu.EmailSignCbx;
                        VytvoritSouborPodaniDto.IxsDpo = this.ixsDpo;
                        VytvoritSouborPodaniDto.SignWithTimeStamp = this.pod_potv_pdf_cr;
                        this.beginOperation();
                        Gordic.Pod.Utils.VytvorSouborPotvrzeni(this, VytvoritSouborPodaniDto)
                            .done(function (retVal) {
                            that.log.trace("OdeslatPotvrzeni - VytvorSouborPotvrzeni");
                            if (retVal.LzeVolatOeslatPozvrzeni) {
                                that.OdeslatPozvrzeniStart(retVal);
                            }
                            // opt.PodepsatSouborPotvrzeni = retVal
                        })
                            .always(function () {
                            that.endOperation();
                        });
                    }
                    else {
                        that.OdeslatPozvrzeniStart(VytvoritSouborPodaniDto); //předam jen prázdné dto
                    }
                    this.log.trace("OdeslatPotvrzeni- end");
                }
                /**
                 * call odeslání potvrzení
                 *
                 * @param {GEvidenceElPodaniVytvoritSouborPodaniDto} SouborPodaniDto
                 */
                OdeslatPozvrzeniStart(SouborPodaniDto) {
                    this.log.trace("OdeslatPozvrzeniStart- start");
                    const that = this;
                    var opt = {};
                    opt.NoCbx = this.Krok6VysledekFormu.NoCbx;
                    opt.DSCbx = this.Krok6VysledekFormu.DSCbx;
                    opt.EmailCbx = this.Krok6VysledekFormu.EmailCbx;
                    opt.PisCbx = this.Krok6VysledekFormu.PisCbx;
                    opt.OdpEmail = this.Krok6VysledekFormu.OdpEmail;
                    opt.OdesIDDS = this.Krok6VysledekFormu.OdesIDDS;
                    opt.DSOdDropDown = (this.Krok6VysledekFormu.DSOdDropDownField && this.Krok6VysledekFormu.DSOdDropDownField.mailbox) ? this.Krok6VysledekFormu.DSOdDropDownField.mailbox : null;
                    opt.IxsEsu = this.Krok6VysledekFormu.OdesIxs;
                    opt.PorZast = this.Krok6VysledekFormu.OdesZastPor;
                    opt.LicZast = this.Krok6VysledekFormu.OdesZastLic;
                    opt.TextPotvrz = this.Krok6VysledekFormu.TextPotvrz;
                    opt.EmailSignCbx = this.Krok6VysledekFormu.EmailSignCbx;
                    opt.ZpusDor = this.VysledekSpustitPodaniDto.ZpusDor;
                    opt.PodpisMailu = SouborPodaniDto.PodpisMailu;
                    opt.IsPotvrzSignedFinal = SouborPodaniDto.IsPotvrzSignedFinal;
                    this.call("OdeslatPotvrzeniSTestem", { inputDto: opt }, undefined /*, { progressState: { text: "jres:31950221" } }*/) //RC 31950221 : Probíhá rozbor el. podání
                        .done(function (retVal) {
                        if (retVal) {
                            that.krok6_callOdeslatPozvrzeniDone(retVal);
                        }
                    })
                        .always(function (val1, val2, val3) {
                        var file = new GFile();
                        if (SouborPodaniDto.ObsahSouboruGUID != null && SouborPodaniDto.ObsahSouboruGUID !== "") {
                            file.removeFile(SouborPodaniDto.ObsahSouboruGUID);
                        }
                        if (SouborPodaniDto.ZpravaPotvrzeniGUID != null && SouborPodaniDto.ZpravaPotvrzeniGUID !== "") {
                            file.removeFile(SouborPodaniDto.ZpravaPotvrzeniGUID);
                        }
                    });
                    this.log.trace("OdeslatPozvrzeniStart- end");
                }
                /**
                 * zpracování callu potvrzení
                 *
                 * @param {Gordic.Pod.WebControls.GEvidenceElPodaniOdeslatPotvrzeniDto} dto
                 */
                krok6_callOdeslatPozvrzeniDone(dto) {
                    const that = this;
                    this.Krok6VysledekOdeslatPozvrzeni = dto;
                    this.zkontrolujHlasku(dto.Hlasky.Hlaska, "Informace").done(function () {
                        that.zkontrolujHlasku(dto.Hlasky.Hlaska2, "Informace").done(function () {
                            that.zkontrolujHlasku(dto.Hlasky.Hlaska3, "Informace").done(function () {
                                //vykonyKod
                                if (dto.PotvrzeniOdeslano) {
                                    that.notification("showToast", { icon: "fa-check", content: "jres:31950320", state: "success" }, { delay: 6 }); //RC 31950320 : Bylo vygenerováno potvrzení pro vybraný externí subjekt.
                                }
                                if (that.testIfCloseForm()) {
                                    return;
                                } // pokud byl nastaven příznak na zavření někde.
                                var parentcontent = that.parentContent;
                                that.ZavreniBezOtazky = true;
                                that.tryClose(); // možná that.tryCloseOdemkni();
                                if (dto.OtevriDetailZasilky) {
                                    that.otevriDetailZasilky(dto.Sxs, parentcontent);
                                }
                            });
                        });
                    });
                }
                /**
                 * funkce pro otevřeníé detailui zásily
                 *
                 * @param {string} sxs
                 */
                otevriDetailZasilky(sxs, parentContent) {
                    var opt = { Sxs: sxs };
                    Gordic.Wfl.Dialogs.GDetailZasilkyDlg(parentContent, opt, Gordic.Global.Enums.ModOtevreni.navigate);
                }
                //#endregion
                //#region hlasky a dotazy
                zkontrolujHlasku(hlaska, nadpis) {
                    let promis = $.Deferred();
                    if (hlaska) {
                        this.dialogs.alert(nadpis, hlaska).on("closed", function (ev) {
                            promis.resolve();
                        });
                    }
                    else {
                        promis.resolve();
                    }
                    return promis.promise();
                }
                zkontrolujInitHlasku(NactiDto, hodnota) {
                    let promis = $.Deferred();
                    if (hodnota) {
                        this.dialogs.alert("jres:31950144", hodnota).on("closed", function (ev) {
                            promis.resolve();
                        });
                    }
                    else {
                        promis.resolve();
                    }
                    return promis.promise();
                }
                zkontrolujInitDotaz(NactiDto) {
                    let promis = $.Deferred();
                    if (NactiDto.UkazDotaz && NactiDto.DotazTxt && !NactiDto.JednaSeOOdpoved) {
                        this.dialogs.confirm("jres:23900067", NactiDto.DotazTxt).on("closed", function (ev, retVal) {
                            if (retVal === "yes") {
                                NactiDto.DotazPotvrzen = true;
                            }
                            else {
                                NactiDto.CloseForm = true;
                            }
                            promis.resolve();
                        });
                    }
                    else {
                        promis.resolve();
                    }
                    return promis.promise();
                }
                // krok1
                zkontrolujKrok1DotazOdmitnuti(krok1Dto) {
                    const that = this;
                    let promis = $.Deferred();
                    if (krok1Dto.QuestionDto.OdmitnoutPodani) {
                        this.dialogs.confirm("jres:23900067", krok1Dto.QuestionDto.OdmitnoutPodaniTxt).on("closed", function (ev, retVal) {
                            if (retVal === "yes") {
                                that.odmitnoutNecitelne(true);
                                // TODO     Odmitnout
                                promis.reject();
                            }
                            else {
                                //Neodmítnout
                                that.tryCloseOdemkni();
                                promis.reject();
                            }
                        });
                    }
                    else {
                        promis.resolve();
                    }
                    return promis.promise();
                }
                zkontrolujKrok1DotazPostoupeni(krok1Dto) {
                    let promis = $.Deferred();
                    if (krok1Dto.QuestionDto.Postoupeni) {
                        this.dialogs.confirm("jres:23900067", krok1Dto.QuestionDto.PostoupeniTxt).on("closed", function (ev, retVal) {
                            if (retVal === "yes") {
                                krok1Dto.IsPostoupeni = true;
                            }
                            else {
                                //Nepostoupeni
                            }
                            promis.resolve();
                        });
                    }
                    else {
                        promis.resolve();
                    }
                    return promis.promise();
                }
