                stahnoutZpravuFinal(guid) {
                    var that = this;
                    this.beginOperation();
                    var file = new GFile();
                    var opt = {
                        guid: guid
                    };
                    this.log.trace("stahnoutZpravuFinal guid:" + guid);
                    file.download(opt)
                        .then(function () {
                        that.log.trace("Proběhlo stažení souboru.");
                        that.showFlash("jres:31950249", "success", "StazeniSouboru"); //RC 31950249 : Proběhlo stažení souboru.
                        that.endOperation();
                    }, function () {
                        that.log.trace("Stažení nedopadlo");
                        that.endOperation();
                        return;
                    })
                        .always(function () {
                        file.removeFile(guid);
                    });
                }
