                rozeberMailVMailu() {
                    const that = this;
                    var inputDto = {};
                    inputDto.ZpusDor = this.VysledekSpustitPodaniDto.ZpusDor;
                    inputDto.FileNameZpravaVeZprave = this.VysledekKrok1Call1.FileNameZpravaVeZprave;
                    inputDto.JeAntivir = this.VysledekSpustitPodaniDto.JeAntivir;
                    inputDto.NoAntivir = this.VysledekSpustitPodaniDto.NoAntivir;
                    inputDto.OrigEml = this.getOrigEml();
                    inputDto.StavInb = this.VysledekSpustitPodaniDto.StavInb;
                    this.call("RozeberMailVMailu", { inputDto: inputDto }, undefined /*, { progressState: { text: "jres:31950220" } }*/ /*, { progressState: "Načítám data" }*/) //RC 31950220 : Načítám data
                        .done(function (retVal) {
                        if (retVal) {
                            that.zkontrolujHlasku(retVal.Hlaska, "jres:31950144").done(function () {
                                //sekce GEx 
                                if (retVal.GexNedopadl) {
                                    if (retVal.TextOdmitnoutPodani) {
                                        that.dialogs.confirm("jres:31950284", retVal.TextOdmitnoutPodani).on("closed", function (ev, retVal) {
                                            if (retVal === "yes") {
                                                that.odmitnoutNecitelne(false);
                                            }
                                            else {
                                                if (retVal.GexNedopadlMsgPrazdne) {
                                                    that.tryCloseOdemkni();
                                                    return;
                                                }
                                            }
                                        });
                                    }
                                }
                                if (retVal.DZpoleDto) {
                                    that.UpravHodnotyPodleDZPole(retVal.DZpoleDto);
                                }
                                //sekce gex end
                                if (retVal.Krok1Dto && retVal.Krok1Dto.DZPole) {
                                    that.UpravHodnotyPodleDZPole(retVal.Krok1Dto.DZPole);
                                }
                                that.ZpracovatJakoMsgInMsg = retVal.ZpracovatJakoMsgInMsg;
                                if (retVal.ZpracovatJakoMsgInMsg) {
                                    that.PolePovolenychKroku[1] = true;
                                    if (retVal.CisKrok === 0) {
                                        that.aktualniCisloKroku = 0;
                                        that.provedenoKroku = 0;
                                        that.spustitPodaniZnovu();
                                    }
                                    else if (retVal.CisKrok === 1) {
                                        that.aktualniCisloKroku = 1;
                                        that.provedenoKroku = 1;
                                        that.pokracuj();
                                    }
                                }
                            });
                        }
                    });
                }
