                zmenaStepu(nextStep) {
                    if (this.PouzePrehled) {
                        return;
                    }
                    //nextStep = nextStep + 1; // aby se neindexovalo od nuly
                    this.resetVsehoOdKroku(nextStep + 1); // posíláme o 2 číslo větší protože se tu motají jmena kroku s indexem v poli a resetuju od následujícího kroku
                    switch (nextStep) {
                        case 1:
                            this.PolePovolenychKroku[3] = false;
                        case 2:
                            this.PolePovolenychKroku[4] = false;
                        case 3:
                            this.PolePovolenychKroku[5] = false;
                            //case 4:
                            //    this.PolePovolenychKroku[5] = false;
                            break;
                        default:
                    }
                    if (!this.KontrolaFormatuIsOK && (this.DuvodOdmitnuti == null || this.DuvodOdmitnuti == 0 /* Interface.DuvodOdmitnutiElPodani.neurceno */)) { // pokud se odmítá podání, tak k resetu nesmí dojít
                        this.PolePovolenychKroku[4] = false;
                        this.PolePovolenychKroku[5] = false;
                    }
                    if (this.hystorickyNastavenVynutitOriginal) { // pro jistotu abych nerozbil něco jiného, provádím jen když byl problem s originalem
                        this.zkontrolujHlaskuVynutitOriginal();
                        if (this.VynutitOriginal && (this.DuvodOdmitnuti == null || this.DuvodOdmitnuti == 0 /* Interface.DuvodOdmitnutiElPodani.neurceno */)) { // pokud se odmítá podání, tak k resetu nesmí dojít
                            this.PolePovolenychKroku[3] = false;
                            this.PolePovolenychKroku[4] = false;
                            this.PolePovolenychKroku[5] = false;
                        }
                        else {
                            this.PolePovolenychKroku[3] = true;
                        }
                    }
                }
                resetVsehoOdKroku(krokNaKteremZacneReset, hardReset) {
                    var resetovat = true;
                    if (this.provedenoKroku > krokNaKteremZacneReset) {
                        this.provedenoKroku = krokNaKteremZacneReset;
                    }
                    else if (hardReset) {
                        resetovat = true;
                    }
                    else {
                        resetovat = false;
                    }
                    // Pozor switch bez breaku aby to šlo pekne postupně
                    switch (krokNaKteremZacneReset) {
                        case 0:
                            this.krokx_setniIkonku(1, "nic");
                        case 1:
                            this.krokx_setniIkonku(2, "nic");
                        case 2:
                            if (resetovat)
                                this.Step2_MaAktualniDataProVykresleni = false;
                            this.krokx_setniIkonku(3, "nic");
                        case 3:
                            if (resetovat)
                                this.Step3_MaAktualniDataProVykresleni = false;
                            this.krokx_setniIkonku(4, "nic");
                        case 4:
                            if (resetovat)
                                this.Step4_MaAktualniDataProVykresleni = false;
                            this.krokx_setniIkonku(5, "nic");
                        case 5:
                            if (resetovat)
                                this.Step5_MaAktualniDataProVykresleni = false;
                            this.krokx_setniIkonku(6, "nic");
                        case 6:
                            if (resetovat)
                                this.Step6_MaAktualniDataProVykresleni = false;
                            break;
                        default:
                    }
                }
